add_action('wp_head', 'stillness_quiz_print_styles', 99);
function stillness_quiz_print_styles()
{
    ?>
    <style id="stillness-quiz-styles">
    .stillness-quiz,[class*="stillness-quiz"]{--sq-ink:#0E1B30;--sq-midnight:#1D3152;--sq-seafoam:#688F9D;--sq-wave:#A4B2BA;--sq-breeze:#D9E8EB;--sq-sand:#C4BBB4;--sq-cream:#F7F0EC;--sq-warm:#F2E8DF;--sq-white:#FFFFFF;--sq-teal:#2C7A7B;--sq-accent:var(--sq-teal);max-width:660px;margin:0 auto;padding:clamp(2rem,4vw,3rem) 1.5rem 2.5rem;color:var(--sq-ink);font-family:'Lato',sans-serif;font-weight:300;font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased;box-sizing:border-box}.stillness-quiz *,.stillness-quiz *::before,.stillness-quiz *::after{box-sizing:border-box}.stillness-quiz h2{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(1.5rem,4.5vw,2rem);line-height:1.25;color:var(--sq-ink);margin:0 0 1rem}.stillness-quiz h3{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:1.5rem;line-height:1.3;color:var(--sq-ink);margin:0 0 0.75rem}.stillness-quiz p{color:rgba(14,27,48,0.6);margin:0 0 1rem}.sq-progress{height:2px;background:rgba(14,27,48,0.12);border-radius:99px;overflow:hidden;margin-bottom:0.75rem}.sq-progress-bar{height:100%;background:var(--sq-accent);transition:width 0.45s cubic-bezier(0.4,0,0.2,1)}.sq-counter{font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(14,27,48,0.5);margin-bottom:1.25rem}.sq-counter span{opacity:0.55}.sq-options{display:flex;flex-direction:column;gap:10px}.sq-option{display:flex;align-items:flex-start;gap:18px;width:100%;text-align:left;background:#FFFFFF;border:1px solid rgba(14,27,48,0.12);border-radius:14px;padding:14px 20px;cursor:pointer;font-family:'Lato',sans-serif;font-size:15px;line-height:1.5;color:var(--sq-ink);transition:all 0.25s cubic-bezier(0.16,1,0.3,1);appearance:none;box-shadow:0 2px 8px rgba(14,27,48,0.02)}.sq-option:hover{border-color:var(--sq-teal);background:rgba(44,122,123,0.05);color:var(--sq-ink);transform:translateY(-2px);box-shadow:0 8px 20px rgba(44,122,123,0.12)}.sq-option:hover .sq-option-key{border-color:var(--sq-teal);color:var(--sq-teal);background:rgba(44,122,123,0.1)}.sq-option:focus-visible{outline:2px solid var(--sq-accent);outline-offset:3px}.sq-option.is-selected{border-color:var(--sq-teal);background:rgba(44,122,123,0.08);color:var(--sq-ink);box-shadow:0 8px 24px rgba(44,122,123,0.15)}.sq-option.is-selected:hover{background:rgba(44,122,123,0.13);border-color:var(--sq-teal);color:var(--sq-ink);transform:translateY(-2px);box-shadow:0 8px 24px rgba(44,122,123,0.2)}.sq-option.is-selected:hover .sq-option-key{border-color:var(--sq-teal);background:var(--sq-teal);color:#FFFFFF}.sq-option-key{flex:0 0 auto;width:26px;height:26px;border:1px solid rgba(14,27,48,0.2);border-radius:50%;display:grid;place-items:center;font-size:11px;color:rgba(14,27,48,0.6);transition:all 0.25s ease}.sq-option.is-selected .sq-option-key{border-color:var(--sq-teal);background:var(--sq-teal);color:#FFFFFF}.sq-option-text{flex:1 1 auto}.sq-nav{display:flex;gap:12px;margin-top:1.5rem}.sq-btn{padding:16px 32px;border-radius:99px;border:1px solid rgba(14,27,48,0.16);background:transparent;cursor:pointer;font-family:'Lato',sans-serif;font-size:13px;color:var(--sq-ink);transition:all 0.3s cubic-bezier(0.16,1,0.3,1)}.sq-btn:hover:not(:disabled){border-color:var(--sq-teal);color:var(--sq-teal);background:rgba(44,122,123,0.05);transform:translateY(-1px)}.sq-btn-next{background:var(--sq-ink);color:#FFFFFF;border-color:var(--sq-ink);margin-left:auto}.sq-btn-next:hover:not(:disabled){background:var(--sq-teal);color:#FFFFFF;border-color:var(--sq-teal);transform:translateY(-2px);box-shadow:0 8px 24px rgba(44,122,123,0.3)}.sq-btn:disabled{opacity:0.3;cursor:default}.sq-form{display:flex;flex-direction:column}.sq-form label{font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:rgba(14,27,48,0.5);margin-top:0.875rem}.sq-form input{font-family:'Lato',sans-serif;font-size:16px;font-weight:300;padding:14px 0;border:none;border-bottom:1px solid rgba(14,27,48,0.14);background:transparent;color:var(--sq-ink);border-radius:0;transition:border-bottom-color 0.25s ease}.sq-form input:focus{outline:none;border-bottom-color:var(--sq-teal)}.sq-cta{display:inline-block;background:var(--sq-ink);color:#FFFFFF;padding:18px 44px;border-radius:99px;border:none;cursor:pointer;font-family:'Lato',sans-serif;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.14em;text-decoration:none;transition:all 0.3s cubic-bezier(0.16,1,0.3,1);margin-top:1.5rem}.sq-cta:hover:not(:disabled){background:var(--sq-teal);color:#FFFFFF;transform:translateY(-2px);box-shadow:0 10px 28px rgba(44,122,123,0.35)}.sq-checkout-form .sq-cta{margin-top:0}.sq-error{color:#A6472F;font-size:13px;margin:0.875rem 0 0}.sq-legal{font-size:13px;color:rgba(14,27,48,0.5);margin:1.25rem 0 0}.sq-loading{text-align:center;padding:2rem 0}.sq-spinner{display:block;width:28px;height:28px;margin:0 auto 1.25rem;border:1px solid rgba(14,27,48,0.15);border-top-color:var(--sq-teal);border-radius:50%;animation:sq-spin 0.8s linear infinite}@keyframes sq-spin{to{transform:rotate(360deg)}}.sq-result{border-top:2px solid var(--sq-accent);padding-top:1.5rem}.sq-eyebrow{font-size:11px;letter-spacing:0.2em;text-transform:uppercase;color:rgba(14,27,48,0.5);margin-bottom:1rem}.sq-result-name{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(2rem,6vw,3rem);line-height:1.1;color:var(--sq-ink);margin-bottom:0.625rem}.sq-tagline{font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:var(--sq-accent);margin-bottom:1rem}.sq-short{font-size:19px;line-height:1.6;margin-bottom:2rem}.sq-prescription{margin-bottom:2rem}.sq-prescription ol{list-style:none;margin:0;padding:0;counter-reset:sq-p}.sq-prescription li{counter-increment:sq-p;padding:1rem 0;border-top:1px solid rgba(14,27,48,0.12);display:grid;grid-template-columns:32px 1fr;gap:0 18px}.sq-prescription li::before{content:counter(sq-p);font-size:11px;color:rgba(14,27,48,0.5);padding-top:6px}.sq-prescription li strong{display:block;font-weight:700}.sq-prescription li span{display:block;color:rgba(14,27,48,0.6);font-size:15px}.sq-unlock{background:rgba(14,27,48,0.035);border-radius:20px;padding:1.75rem}.sq-unlock > p{margin-bottom:1.25rem}.stillness-quiz-locked{font-family:'Lato',sans-serif;font-size:15px;color:rgba(14,27,48,0.6);padding:1.5rem;background:rgba(14,27,48,0.03);border-radius:14px}@media (max-width:480px){.stillness-quiz{padding:2rem 1.25rem}.sq-nav{flex-direction:column-reverse}.sq-btn-next{margin-left:0}.sq-unlock{padding:1.5rem 1.25rem}.sq-short{margin-bottom:1.5rem}}@media (prefers-reduced-motion:reduce){.stillness-quiz *,.stillness-quiz *::before,.stillness-quiz *::after{transition:none;animation:none}}.sq-unlock--done{background:rgba(44,122,123,0.07)}.sq-restart{margin:2rem 0 0}.sq-restart-btn{background:transparent;border:none;border-bottom:1px solid rgba(14,27,48,0.2);padding:0 0 3px;cursor:pointer;font-family:'Lato',sans-serif;font-size:12px;letter-spacing:0.16em;text-transform:uppercase;color:rgba(14,27,48,0.5);transition:color 0.25s ease,border-color 0.25s ease}.sq-restart-btn:hover{color:var(--sq-teal);border-bottom-color:var(--sq-teal)}.sq-restart-btn:focus-visible{outline:2px solid var(--sq-teal);outline-offset:4px}.stillness-quiz-prescription{border-top:2px solid var(--sq-accent)}.stillness-quiz-prescription h2{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:clamp(2rem,6vw,3rem);line-height:1.1;margin:0.5rem 0 0.75rem}.stillness-quiz-tagline{font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:var(--sq-accent);margin:0}.stillness-quiz-prescription h3{font-family:'Cormorant Garamond',serif;font-weight:300;font-size:1.5rem;margin:2rem 0 0.75rem}.stillness-quiz-practices ol{list-style:none;margin:0;padding:0;counter-reset:sq-p}.stillness-quiz-practices li{counter-increment:sq-p;padding:1rem 0;border-top:1px solid rgba(14,27,48,0.12);display:grid;grid-template-columns:32px 1fr;gap:0 18px}.stillness-quiz-practices li::before{content:counter(sq-p);font-size:11px;color:rgba(14,27,48,0.5);padding-top:6px}.stillness-quiz-practices li strong{display:block;font-weight:700}.stillness-quiz-practices li span{display:block;color:rgba(14,27,48,0.6)}.stillness-quiz-downloads{margin:2rem 0 0;padding-top:1.5rem;border-top:1px solid rgba(14,27,48,0.12)}.stillness-quiz-downloads a{color:var(--sq-teal);text-decoration:none}.stillness-quiz-downloads a:hover{text-decoration:underline}
    .sq-multi-hint{margin:0 0 12px;font-family:'Jost',sans-serif;font-size:12px;letter-spacing:0.08em;text-transform:uppercase;color:rgba(14,27,48,0.6)}
