add_action('wp_footer', 'stillness_quiz_print_script', 99);
function stillness_quiz_print_script()
{
    ?>
    <script id="stillness-quiz-script">
    (function(){'use strict';var K=['A','B','C','D'],D='stillness_quiz_draft',H='stillness_quiz_handoff',s={answers:{},current:0};function e(x){return document.getElementById(x)}function q(x){var n=document.createElement('div');n.textContent=x==null?'':String(x);return n.innerHTML}function save(){try{sessionStorage.setItem(D,JSON.stringify(s.answers))}catch(x){}}function sel(v,m){if(typeof v!=='string'||!v)return null;var u=v.split(''),i;for(i=0;i<u.length;i++){if(K.indexOf(u[i])<0||u.indexOf(u[i])!==i)return null}return m||u.length===1?u:null}function add(t,w,u){var i,j;for(i=0;i<u.length;i++)for(j=0;j<4;j++)t[K[j]]+=+((w[u[i]]||{})[K[j]])||0}function score(a){var Q=window.STILLNESS_QUIZ.questions,n=Q.length,t={A:0,B:0,C:0,D:0},i,u;for(i=0;i<n;i++){u=sel(a[i],Q[i].m);if(!u)return null;add(t,Q[i].w||{},u)}var m=Math.max(t.A,t.B,t.C,t.D);if(m<=0)return null;var l=K.filter(function(x){return t[x]===m});if(l.length===1)return l[0];var f={A:0,B:0,C:0,D:0};add(f,Q[n-1].w||{},sel(a[n-1],Q[n-1].m));var b=l[0];l.forEach(function(x){if(f[x]>f[b])b=x});return b}function checkout(k,t,a,f){var id=t&&t.variation_id,b=f.querySelector('button'),url=window.STILLNESS_QUIZ&&window.STILLNESS_QUIZ.cart_url;if(!id||!url){err('The prescription is not set up in the shop yet. Please let us know and we will finish your access.');return}try{sessionStorage.setItem(H,JSON.stringify({result:k,answers:a}))}catch(x){}if(b){b.disabled=true;b.textContent='Taking you to checkout…'}fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},body:'product_id='+encodeURIComponent(id)+'&quantity=1'}).then(function(r){return r.json()}).then(function(x){if(x&&x.error){if(b){b.disabled=false;b.textContent='Unlock the full prescription'}inline(f,'We could not add the prescription just now. Please try again.');return}window.location.href=window.STILLNESS_QUIZ.checkout_url}).catch(function(){if(b){b.disabled=false;b.textContent='Unlock the full prescription'}inline(f,'We could not reach the shop just now. Please try again.')})}function inline(f,m){var x=f.querySelector('.sq-error');if(!x){x=document.createElement('p');x.className='sq-error';x.setAttribute('role','alert');f.appendChild(x)}x.textContent=m}function hydrate(){var r=e('stillness_quiz_result'),a=e('stillness_quiz_answers');if(!r||r.value)return;try{var x=JSON.parse(sessionStorage.getItem(H)||'null');if(x&&x.result){r.value=x.result;if(a&&x.answers)a.value=x.answers}}catch(z){}}function question(){var r=e('stillness-quiz'),x=window.STILLNESS_QUIZ.questions,i=s.current,c=s.answers[i]||'',m=!!x[i].m,n=x.length;r.innerHTML='<div class="sq-progress"><div class="sq-progress-bar" style="width:'+((i+1)/n*100)+'%"></div></div><p class="sq-counter">'+(i+1)+' <span>of '+n+'</span></p><h2>'+q(x[i].q)+'</h2>'+(m?'<p class="sq-multi-hint">Select all that apply</p>':'')+'<div class="sq-options" role="'+(m?'group':'radiogroup')+'">'+K.map(function(k){return'<button type="button" class="sq-option'+(c.indexOf(k)>-1?' is-selected':'')+'" role="'+(m?'checkbox':'radio')+'" aria-checked="'+(c.indexOf(k)>-1)+'" data-key="'+k+'"><span class="sq-option-key">'+k+'</span><span>'+q(x[i].o[k])+'</span></button>'}).join('')+'</div><div class="sq-nav"><button type="button" class="sq-btn" data-back '+(i===0?'disabled':'')+'>Back</button><button type="button" class="sq-btn sq-btn-next" data-next '+(c?'':'disabled')+'>'+(i===n-1?'See my result':'Next')+'</button></div>';Array.prototype.forEach.call(r.querySelectorAll('.sq-option'),function(b){b.onclick=function(){var k=b.getAttribute('data-key');if(m){var u=(s.answers[s.current]||'').split('').filter(Boolean),p=u.indexOf(k);if(p<0)u.push(k);else u.splice(p,1);u.sort();if(u.length)s.answers[s.current]=u.join('');else delete s.answers[s.current]}else s.answers[s.current]=k;save();question()}});r.querySelector('[data-back]').onclick=function(){if(s.current){s.current--;question()}};r.querySelector('[data-next]').onclick=function(){if(s.answers[s.current]){if(s.current<n-1){s.current++;question()}else gate()}}}function gate(){var r=e('stillness-quiz'),g=window.STILLNESS_QUIZ.gate;r.innerHTML='<h2>'+q(g.heading)+'</h2><p>'+q(g.body)+'</p><form class="sq-form" id="sq-gate" novalidate><label>Name</label><input id="sq-name" autocomplete="given-name" required><label>Email</label><input id="sq-email" type="email" autocomplete="email" required><p class="sq-error" hidden></p><button class="sq-cta">'+q(g.button)+'</button></form><p class="sq-legal">'+q(g.legal)+'</p>';e('sq-gate').onsubmit=function(v){v.preventDefault();var n=e('sq-name').value.trim(),m=e('sq-email').value.trim(),z=this.querySelector('.sq-error');if(!n||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m)){z.textContent='Please enter your name and a valid email.';z.hidden=false;return}submit(n,m)}}function submit(n,m){var local=score(s.answers),r=e('stillness-quiz');if(!local){r.innerHTML='<p class="sq-error">Something went wrong. Please retake the diagnostic.</p>';return}r.innerHTML='<div class="sq-loading"><span class="sq-spinner"></span><p>Reading your answers…</p></div>';fetch(window.STILLNESS_QUIZ_REST,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:n,email:m,answers:s.answers,nonce:window.STILLNESS_QUIZ_NONCE})}).then(function(x){return x.json()}).then(function(x){var k=x&&x.result||local;result(k,x&&x.type||window.STILLNESS_QUIZ.types[k],false)}).catch(function(){result(local,window.STILLNESS_QUIZ.types[local],false)})}function result(k,t,open){var r=e('stillness-quiz'),a=JSON.stringify(s.answers),p=t.practices.map(function(x){return'<li><div><strong>'+q(x.title)+'</strong><span>'+q(x.detail)+'</span></div></li>'}).join(''),d=window.STILLNESS_QUIZ.downloads||'',u=open?'<section class="sq-unlock sq-unlock--done"><h3>Your prescription is unlocked</h3>'+(d||'<p>Your downloads are in your confirmation email.</p>')+'</section>':k?'<section class="sq-unlock"><h3>Take this with you</h3><p>Audio practices, workbooks and links for '+q(t.name)+'.</p><form class="sq-checkout-form"><button class="sq-cta">Unlock the full prescription</button></form></section>':'';r.style.setProperty('--sq-accent',t.accent);r.innerHTML='<div class="sq-result"><p class="sq-eyebrow">Your result</p><h2 class="sq-result-name">'+q(t.name)+'</h2><p class="sq-tagline">'+q(t.tagline)+'</p><p class="sq-short">'+q(t.short)+'</p><section class="sq-prescription"><h3>Where to begin</h3><p>'+q(t.intro)+'</p><ol>'+p+'</ol></section>'+u+(k?'<p class="sq-restart"><button class="sq-restart-btn">Retake the diagnostic</button></p>':'')+'</div>';var f=r.querySelector('.sq-checkout-form');if(f)f.onsubmit=function(v){v.preventDefault();checkout(k,t,a,f)};var b=r.querySelector('.sq-restart-btn');if(b)b.onclick=function(){try{sessionStorage.removeItem(D)}catch(x){}s.answers={};s.current=0;question()}}function boot(){var r=e('stillness-quiz'),c=window.STILLNESS_QUIZ;if(!r||!c)return;if(c.type&&!c.questions.length){result(null,c.type,c.unlocked);return}try{s.answers=JSON.parse(sessionStorage.getItem(D)||'{}')}catch(x){}question()}function init(){hydrate();boot()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();window.addEventListener('load',hydrate)})();
    </script>
    <?php
}
